<script setup lang="ts">
import { nextTick, onMounted, ref } from 'vue'
import { CalendarClock, MapPin, MessageCircle, Save, Settings, ShieldCheck, X } from 'lucide-vue-next'

type Tab='agenda'|'phone'|'security'|'whatsapp'
type FieldMode='DISABLED'|'OPTIONAL'|'REQUIRED'
type Envelope<T>={data?:T;error?:{message?:string}}
type BookingParameters={
  service_mode:FieldMode;email_mode:FieldMode;phone_mode:FieldMode;duration_mode:FieldMode;professional_mode:FieldMode;
  default_duration_minutes:number;default_professional_name:string;default_customer_mode:'NEW'|'EXISTING';
  simultaneous:{public:boolean;internal:boolean;capacity:number;enforce_public:boolean;enforce_internal:boolean};
  rules:{enforce_business_hours:boolean;enforce_blocked_periods:boolean};
  minimum_notice_minutes:number;phone:{country:string;country_code:string;area_code:string;add_ninth_digit:boolean}
}
type TwoFactorState={enabled:boolean;configured:boolean;mandatory:boolean;second_factor_verified:boolean}
type Enrollment={manual_key:string;qr_code:string;otpauth_uri:string}
type WhatsStatus={product?:string;instance_name?:string;status:string;connection_method?:string|null;phone?:string|null;qr?:{base64?:string|null;pairing_code?:string|null;code?:string|null;count?:number|null}|null;pairing_code?:string|null;provider?:Record<string,unknown>}
type Capabilities={enabled:string[]}

const active=ref(false),tab=ref<Tab>('agenda'),portalReady=ref(false),loading=ref(false),saving=ref(false),errorMessage=ref(''),successMessage=ref('')
const params=ref<BookingParameters>({service_mode:'REQUIRED',email_mode:'OPTIONAL',phone_mode:'REQUIRED',duration_mode:'REQUIRED',professional_mode:'REQUIRED',default_duration_minutes:60,default_professional_name:'Agenda geral',default_customer_mode:'NEW',simultaneous:{public:false,internal:false,capacity:1,enforce_public:true,enforce_internal:true},rules:{enforce_business_hours:true,enforce_blocked_periods:true},minimum_notice_minutes:1440,phone:{country:'BR',country_code:'55',area_code:'',add_ninth_digit:true}})
const twoFactor=ref<TwoFactorState|null>(null),enrollment=ref<Enrollment|null>(null),twoFactorCode=ref(''),disableCode=ref('')
const whatsEnabled=ref(false),whats=ref<WhatsStatus|null>(null),pairingPhone=ref(''),pairingCode=ref(''),testPhone=ref(''),testMessage=ref('Teste de comunicação do Scheduler Pro.')

async function api<T>(path:string,init:RequestInit={}):Promise<T>{const response=await fetch(`/api/v1${path}`,{...init,cache:'no-store',headers:{accept:'application/json',...(init.body?{'content-type':'application/json'}:{}),...(init.headers||{})}});const body=await response.json().catch(()=>({})) as Envelope<T>;if(!response.ok)throw new Error(body.error?.message||`Falha HTTP ${response.status}`);return body.data as T}
function toast(value:string){successMessage.value=value;window.setTimeout(()=>{if(successMessage.value===value)successMessage.value=''},3500)}
function failure(exc:unknown,fallback:string){errorMessage.value=exc instanceof Error?exc.message:fallback}
function whatsStatusLabel(status?:string|null){return({DISCONNECTED:'Desconectado',CONNECTING:'Conectando',CONNECTED:'Conectado',RECONNECTING:'Reconectando',FAILED:'Falha'} as Record<string,string>)[String(status||'').toUpperCase()]||'Desconhecido'}
function modeHelp(mode:FieldMode){return mode==='DISABLED'?'O campo desaparece do Operador e da página pública.':mode==='OPTIONAL'?'O campo aparece, mas pode ficar vazio.':'O campo aparece e deve ser preenchido.'}
async function loadBase(){loading.value=true;errorMessage.value='';try{const[booking,security,capabilities]=await Promise.all([api<BookingParameters>('/settings/booking'),api<TwoFactorState>('/auth/2fa/state'),api<Capabilities>('/settings/capabilities')]);params.value=booking;twoFactor.value=security;whatsEnabled.value=(capabilities.enabled||[]).includes('whatsapp');if(whatsEnabled.value)await loadWhatsStatus(false)}catch(exc){failure(exc,'Não foi possível carregar as configurações.')}finally{loading.value=false}}
async function open(){active.value=true;await loadBase()}
function close(){active.value=false;enrollment.value=null;pairingCode.value='';errorMessage.value=''}
async function saveBooking(){saving.value=true;errorMessage.value='';try{params.value=await api<BookingParameters>('/settings/booking',{method:'PUT',body:JSON.stringify(params.value)});toast('Modelo de negócio da Agenda salvo.');window.dispatchEvent(new CustomEvent('scheduler-pro-revalidate-current-view'))}catch(exc){failure(exc,'Falha ao salvar parâmetros.')}finally{saving.value=false}}
async function beginTwoFactor(){saving.value=true;errorMessage.value='';try{enrollment.value=await api<Enrollment>('/auth/2fa/setup',{method:'POST',body:'{}'})}catch(exc){failure(exc,'Não foi possível iniciar a configuração de segurança.')}finally{saving.value=false}}
async function confirmTwoFactor(){saving.value=true;errorMessage.value='';try{await api('/auth/2fa/confirm',{method:'POST',body:JSON.stringify({code:twoFactorCode.value})});twoFactor.value=await api<TwoFactorState>('/auth/2fa/state');enrollment.value=null;twoFactorCode.value='';toast('Verificação em duas etapas ativada.')}catch(exc){failure(exc,'Código inválido.')}finally{saving.value=false}}
async function disableTwoFactor(){saving.value=true;errorMessage.value='';try{await api('/auth/2fa/disable',{method:'POST',body:JSON.stringify({code:disableCode.value})});twoFactor.value=await api<TwoFactorState>('/auth/2fa/state');disableCode.value='';toast('Verificação em duas etapas desativada.')}catch(exc){failure(exc,'Não foi possível desativar a verificação.')}finally{saving.value=false}}
async function loadWhatsStatus(showError=true){if(!whatsEnabled.value)return;try{whats.value=await api<WhatsStatus>('/integrations/whatsapp/status')}catch(exc){if(showError)failure(exc,'Não foi possível verificar a conexão.')}}
async function connectQr(){saving.value=true;errorMessage.value='';pairingCode.value='';try{whats.value=await api<WhatsStatus>('/integrations/whatsapp/connect/qr',{method:'POST',body:'{}'})}catch(exc){failure(exc,'Não foi possível iniciar a conexão.')}finally{saving.value=false}}
async function connectPairing(){saving.value=true;errorMessage.value='';try{const data=await api<WhatsStatus>('/integrations/whatsapp/connect/pairing',{method:'POST',body:JSON.stringify({phone:pairingPhone.value})});whats.value=data;pairingCode.value=String(data.pairing_code||data.qr?.pairing_code||'')}catch(exc){failure(exc,'Não foi possível gerar o código de pareamento.')}finally{saving.value=false}}
async function reconnectWhats(){saving.value=true;errorMessage.value='';try{whats.value=await api<WhatsStatus>('/integrations/whatsapp/reconnect',{method:'POST',body:'{}'})}catch(exc){failure(exc,'Não foi possível reconectar.')}finally{saving.value=false}}
async function disconnectWhats(){saving.value=true;errorMessage.value='';try{whats.value=await api<WhatsStatus>('/integrations/whatsapp/disconnect',{method:'POST',body:'{}'});pairingCode.value='';toast('WhatsApp desconectado.')}catch(exc){failure(exc,'Não foi possível desconectar.')}finally{saving.value=false}}
async function testWhats(){saving.value=true;errorMessage.value='';try{await api('/integrations/whatsapp/test',{method:'POST',body:JSON.stringify({phone:testPhone.value,message:testMessage.value})});toast('Mensagem de teste aceita para envio.')}catch(exc){failure(exc,'Não foi possível enviar o teste.')}finally{saving.value=false}}
onMounted(async()=>{await nextTick();window.requestAnimationFrame(()=>{portalReady.value=Boolean(document.querySelector('.tenant-console .nav-list')&&document.querySelector('.tenant-console .main-content'))})})
</script>

<template>
  <Teleport v-if="portalReady" to=".tenant-console .nav-list"><button class="nav-item sp-config-nav" @click="open"><Settings :size="19"/><span>Configurações</span></button></Teleport>
  <Teleport v-if="portalReady&&active" to=".tenant-console .main-content">
    <section class="sp-config-root">
      <header class="sp-config-header"><div><span>Scheduler Pro</span><h1>Configurações</h1><p>Modelo de negócio da Agenda, telefones, segurança e comunicação.</p></div><button class="icon" aria-label="Fechar" @click="close"><X :size="20"/></button></header>
      <nav class="sp-config-tabs" aria-label="Seções de configuração"><button :class="{active:tab==='agenda'}" @click="tab='agenda'"><CalendarClock :size="17"/> Modelo da Agenda</button><button :class="{active:tab==='phone'}" @click="tab='phone'"><MapPin :size="17"/> Telefones e Localização</button><button :class="{active:tab==='security'}" @click="tab='security'"><ShieldCheck :size="17"/> Segurança</button><button v-if="whatsEnabled" :class="{active:tab==='whatsapp'}" @click="tab='whatsapp'"><MessageCircle :size="17"/> ARGWS Whatsapp API</button></nav>
      <p v-if="errorMessage" class="sp-config-error" role="alert">{{errorMessage}}</p><p v-if="successMessage" class="sp-config-success">{{successMessage}}</p><div v-if="loading" class="sp-config-loading">Carregando configurações…</div>
      <template v-else>
        <div v-if="tab==='agenda'" class="sp-config-grid">
          <article class="card span-2"><div class="model-intro"><div><span>Modelo de negócio</span><h2>A Agenda deve se adaptar à operação da sua empresa</h2><p>Desative o que não faz sentido. Um Martelinho de Ouro pode trabalhar com vários clientes no mesmo horário e usar o nome da própria empresa como responsável; uma clínica pode manter profissional, tempo e capacidade rígidos.</p></div></div></article>
          <article class="card"><h2>Campos do atendimento</h2><p>Quando um campo é desativado, ele fica invisível no Operador da Agenda e na Página de Agendamento.</p><label>Serviço<select v-model="params.service_mode"><option value="DISABLED">Oculto</option><option value="OPTIONAL">Opcional / livre</option><option value="REQUIRED">Obrigatório</option></select><span>{{modeHelp(params.service_mode)}}</span></label><label>Telefone / WhatsApp<select v-model="params.phone_mode"><option value="DISABLED">Oculto</option><option value="OPTIONAL">Opcional</option><option value="REQUIRED">Obrigatório</option></select><span>{{modeHelp(params.phone_mode)}}</span></label><label>E-mail<select v-model="params.email_mode"><option value="DISABLED">Oculto</option><option value="OPTIONAL">Opcional</option><option value="REQUIRED">Obrigatório</option></select><span>{{modeHelp(params.email_mode)}}</span></label><label>Profissional / responsável<select v-model="params.professional_mode"><option value="DISABLED">Oculto</option><option value="OPTIONAL">Opcional</option><option value="REQUIRED">Obrigatório</option></select><span>{{modeHelp(params.professional_mode)}}</span></label><label>Tempo / duração<select v-model="params.duration_mode"><option value="DISABLED">Oculto</option><option value="OPTIONAL">Opcional</option><option value="REQUIRED">Obrigatório</option></select><span>{{modeHelp(params.duration_mode)}}</span></label></article>
          <article class="card"><h2>Padrões da operação</h2><label>Abrir Operador em<select v-model="params.default_customer_mode"><option value="NEW">Novo cliente</option><option value="EXISTING">Cliente existente</option></select></label><label>Responsável padrão<input v-model.trim="params.default_professional_name" placeholder="Ex.: Roberto Martelinho de Ouro"/><span>Pode ser o nome da empresa quando não existe profissional individual.</span></label><label>Duração interna padrão <span>minutos — usada pelo motor mesmo quando Tempo está oculto</span><input v-model.number="params.default_duration_minutes" type="number" min="5" max="720"/></label><label>Antecedência mínima <span>minutos — use 0 para permitir imediato</span><input v-model.number="params.minimum_notice_minutes" type="number" min="0"/></label></article>
          <article class="card"><h2>Capacidade</h2><label class="check"><input v-model="params.simultaneous.enforce_internal" type="checkbox"/> Aplicar limite de capacidade no Operador interno</label><label v-if="params.simultaneous.enforce_internal" class="check"><input v-model="params.simultaneous.internal" type="checkbox"/> Permitir múltiplos agendamentos simultâneos internos</label><label class="check"><input v-model="params.simultaneous.enforce_public" type="checkbox"/> Aplicar limite de capacidade na Página de Agendamento</label><label v-if="params.simultaneous.enforce_public" class="check"><input v-model="params.simultaneous.public" type="checkbox"/> Permitir múltiplos agendamentos simultâneos públicos</label><label v-if="params.simultaneous.enforce_internal||params.simultaneous.enforce_public">Capacidade máxima simultânea<input v-model.number="params.simultaneous.capacity" type="number" min="1" max="10000"/></label><div v-if="!params.simultaneous.enforce_internal&&!params.simultaneous.enforce_public" class="example"><strong>Agenda livre</strong><span>Não existe limite de quantidade de clientes no mesmo horário.</span></div></article>
          <article class="card"><h2>Regras de horário</h2><label class="check"><input v-model="params.rules.enforce_business_hours" type="checkbox"/> Restringir agendamentos ao expediente configurado</label><label class="check"><input v-model="params.rules.enforce_blocked_periods" type="checkbox"/> Respeitar bloqueios e indisponibilidades</label><p>Desative essas regras somente quando seu modelo de negócio realmente aceitar registros fora dessas restrições.</p></article>
          <div class="actions"><button class="primary" :disabled="saving" @click="saveBooking"><Save :size="17"/> Salvar modelo de negócio</button></div>
        </div>

        <div v-else-if="tab==='phone'" class="sp-config-grid one"><article class="card"><h2>Telefones e Localização</h2><p>Todos os números informados são convertidos para um formato operacional único antes de pesquisar, gravar, parear ou enviar mensagens.</p><div class="fields"><label>País padrão<input v-model.trim="params.phone.country" maxlength="3" placeholder="BR"/></label><label>Código internacional<input v-model.trim="params.phone.country_code" inputmode="numeric" placeholder="55"/></label><label>DDD padrão<input v-model.trim="params.phone.area_code" inputmode="numeric" placeholder="75"/></label><label class="check"><input v-model="params.phone.add_ninth_digit" type="checkbox"/> Adicionar nono dígito automaticamente quando aplicável</label></div><div class="example"><strong>Exemplo</strong><span>Com Brasil +55, DDD 75 e nono dígito ativo:</span><code>88881111 → 5575988881111</code></div></article><div class="actions"><button class="primary" :disabled="saving" @click="saveBooking"><Save :size="17"/> Salvar telefones e localização</button></div></div>

        <div v-else-if="tab==='security'" class="sp-config-grid one"><article class="card"><h2>Verificação em duas etapas</h2><p>Opcional para a empresa. O recurso permanece desativado até ativação explícita.</p><div v-if="twoFactor?.enabled" class="status good"><ShieldCheck :size="20"/><div><strong>Ativada</strong><span>O código do aplicativo autenticador será solicitado nos próximos acessos.</span></div></div><template v-if="!twoFactor?.enabled&&!enrollment"><button class="primary" :disabled="saving" @click="beginTwoFactor">Configurar aplicativo autenticador</button></template><template v-else-if="enrollment"><div class="setup"><img :src="enrollment.qr_code" alt="QR Code do aplicativo autenticador"/><div><strong>Leia o QR Code</strong><p>Ou informe manualmente esta chave:</p><code>{{enrollment.manual_key}}</code></div></div><label>Código de 6 dígitos<input v-model="twoFactorCode" inputmode="numeric" autocomplete="one-time-code" maxlength="8" placeholder="000000"/></label><button class="primary" :disabled="saving||twoFactorCode.length<6" @click="confirmTwoFactor">Ativar verificação</button></template><template v-else><hr/><h3>Desativar</h3><p>Para desativar, confirme com um código atual do autenticador.</p><label>Código atual<input v-model="disableCode" inputmode="numeric" autocomplete="one-time-code" maxlength="8" placeholder="000000"/></label><button class="danger" :disabled="saving||disableCode.length<6" @click="disableTwoFactor">Desativar verificação</button></template></article></div>

        <div v-else-if="tab==='whatsapp'" class="sp-config-grid one"><article class="card"><div class="whats-head"><div><h2>ARGWS Whatsapp API</h2><p>Conecte por QR Code ou por código de pareamento.</p></div><span class="status-pill">{{whatsStatusLabel(whats?.status)}}</span></div><div class="connection-options"><section><h3>QR Code</h3><p>Abra WhatsApp → Dispositivos conectados → Vincular dispositivo.</p><button class="secondary" :disabled="saving" @click="connectQr">Gerar / atualizar QR Code</button><div v-if="whats?.qr?.base64" class="whats-qr"><img :src="whats.qr.base64" alt="QR Code para conexão do WhatsApp"/></div></section><section><h3>Código de pareamento</h3><p>Informe o telefone. A plataforma normaliza o número antes de solicitar o código.</p><label>Telefone<input v-model="pairingPhone" inputmode="tel" placeholder="(75) 98888-1111"/></label><button class="secondary" :disabled="saving||pairingPhone.length<8" @click="connectPairing">Gerar código</button><div v-if="pairingCode" class="pairing"><span>Código de pareamento</span><strong>{{pairingCode}}</strong></div></section></div><div class="actions wrap"><button class="secondary" :disabled="saving" @click="loadWhatsStatus()">Verificar conexão</button><button class="secondary" :disabled="saving" @click="reconnectWhats">Reconectar</button><button class="danger" :disabled="saving" @click="disconnectWhats">Desconectar</button></div><hr/><h3>Testar envio</h3><div class="fields"><label>Telefone<input v-model="testPhone" inputmode="tel" placeholder="(75) 98888-1111"/></label><label class="wide">Mensagem<input v-model="testMessage"/></label></div><button class="secondary" :disabled="saving||testPhone.length<8" @click="testWhats">Enviar teste</button></article></div>
      </template>
    </section>
  </Teleport>
</template>

<style scoped>
.sp-config-root{display:grid;gap:18px;padding:clamp(16px,3vw,30px);min-height:100%;background:var(--sp-bg,#f6f8fc);color:var(--sp-text,#172033)}.sp-config-header{display:flex;justify-content:space-between;gap:20px;align-items:flex-start}.sp-config-header span{color:#526fd7;font-size:.72rem;font-weight:800;text-transform:uppercase;letter-spacing:.08em}.sp-config-header h1{margin:4px 0;font-size:clamp(1.7rem,4vw,2.35rem)}.sp-config-header p,.card p{margin:0;color:#52647c;line-height:1.55}.icon{width:42px;height:42px;border:0;border-radius:12px;background:#fff;display:grid;place-items:center;cursor:pointer}.sp-config-tabs{display:flex;gap:8px;overflow:auto;padding-bottom:4px}.sp-config-tabs button{display:flex;gap:7px;align-items:center;white-space:nowrap;border:1px solid #dfe4ee;background:#fff;padding:10px 13px;border-radius:12px;font:inherit;font-weight:700;cursor:pointer}.sp-config-tabs button.active{background:#263f9c;color:#fff;border-color:#263f9c}.sp-config-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.sp-config-grid.one{grid-template-columns:1fr}.card{display:grid;gap:16px;padding:20px;border:1px solid #e2e6ef;border-radius:18px;background:#fff;box-shadow:0 7px 28px rgba(22,34,65,.05)}.card.span-2{grid-column:1/-1}.card h2,.card h3{margin:0}.card hr{width:100%;border:0;border-top:1px solid #e7eaf0}.model-intro>div>span{display:block;margin-bottom:5px;color:#2563eb;font-size:10px;font-weight:900;text-transform:uppercase;letter-spacing:.1em}.model-intro h2{font-size:clamp(1.25rem,3vw,1.7rem)}label{display:grid;gap:7px;font-weight:700;color:#3b4558}label>span{font-size:.78rem;font-weight:500;color:#64748b;line-height:1.45}input,select{box-sizing:border-box;width:100%;min-height:44px;border:1px solid #cfd6e2;border-radius:10px;padding:9px 11px;background:#fff;font:inherit;color:inherit}.check{display:flex;align-items:center;gap:9px}.check input{width:18px;min-height:18px;flex:0 0 auto}.fields{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.fields .wide{grid-column:span 2}.actions{grid-column:1/-1;display:flex;justify-content:flex-end;gap:8px}.actions.wrap{justify-content:flex-start;flex-wrap:wrap}button.primary,button.secondary,button.danger{display:inline-flex;align-items:center;justify-content:center;gap:7px;min-height:44px;border-radius:11px;padding:0 15px;font:inherit;font-weight:800;cursor:pointer}.primary{border:0;background:#3151cf;color:#fff}.secondary{border:1px solid #ccd4e2;background:#fff;color:#28334a}.danger{border:1px solid #efcaca;background:#fff7f7;color:#aa2525}button:disabled{opacity:.55;cursor:progress}.example{display:grid;gap:5px;padding:14px;border-radius:13px;background:#f4f6fb}.example code{font-size:1rem;font-weight:800;color:#263f9c}.status{display:flex;align-items:center;gap:10px;padding:14px;border-radius:13px}.status.good{background:#eefaf3;color:#197144}.status div{display:grid;gap:3px}.status span{font-size:.85rem;color:#52705e}.setup{display:grid;grid-template-columns:180px 1fr;gap:18px;align-items:center}.setup img,.whats-qr img{display:block;width:100%;height:auto}.setup img{padding:8px;box-sizing:border-box;border:1px solid #e0e4ec;border-radius:14px}.setup code{display:block;overflow-wrap:anywhere;padding:10px;border-radius:9px;background:#f3f5f8}.whats-head{display:flex;justify-content:space-between;gap:16px}.status-pill{height:max-content;padding:7px 10px;border-radius:999px;background:#edf1ff;color:#2945ad;font-weight:800;font-size:.82rem}.connection-options{display:grid;grid-template-columns:1fr 1fr;gap:14px}.connection-options>section{display:grid;gap:11px;padding:16px;border:1px solid #e3e7ee;border-radius:15px}.connection-options p{font-size:.9rem}.whats-qr{width:min(100%,240px);justify-self:center;padding:10px;border:1px solid #e1e5ed;border-radius:15px}.pairing{display:grid;gap:4px;padding:13px;border-radius:12px;background:#f2f5ff;text-align:center}.pairing span{font-size:.8rem}.pairing strong{font-size:1.45rem;letter-spacing:.08em}.sp-config-error,.sp-config-success,.sp-config-loading{margin:0;padding:12px 14px;border-radius:12px}.sp-config-error{background:#fff0f0;color:#a62323}.sp-config-success{background:#eefaf3;color:#197144}.sp-config-loading{background:#fff;color:#657086}
@media(max-width:800px){.sp-config-grid,.connection-options{grid-template-columns:1fr}.card.span-2{grid-column:auto}.fields{grid-template-columns:1fr}.fields .wide{grid-column:auto}.setup{grid-template-columns:1fr}.setup img{width:min(65vw,220px);justify-self:center}.actions{justify-content:stretch}.actions button{flex:1}.sp-config-root{padding:14px}.sp-config-tabs{margin-inline:-14px;padding-inline:14px}.whats-head{align-items:flex-start;flex-direction:column}}@media(max-width:520px){.card{padding:16px}.actions{display:grid}.sp-config-tabs button{font-size:11px}}
</style>
